// Entrada del item
const item = items[0];
const preguntas = item.json.query.preguntas || "";
const modelo = item.json.query.modelo || "";

// Extraer tipoOrigen (primer palabra antes de "Forma de pago")
const tipoOrigenMatch = preguntas.match(/^(.*?)\s+Forma de pago/i);
const tipoOrigen = tipoOrigenMatch ? tipoOrigenMatch[1].trim() : "";

// Extraer forma de pago (lo que sigue a "Forma de pago:")
const formaDePagoMatch = preguntas.match(/Forma de pago:\s*([^,]+)/i);
const formaDePago = formaDePagoMatch ? formaDePagoMatch[1].trim() : "";

// Extraer usado (lo que sigue a "Usado:")
const usadoMatch = preguntas.match(/Usado:\s*([^,]+)/i);
const usado = usadoMatch ? usadoMatch[1].trim() : "";

// Extraer Boca de venta (del objeto query directamente)
const bocadeventa = item.json.query["Boca de venta "] || "";

// Mapping de modelos -> código
const modeloMap = {
  "Hilux": 1,
  "Corolla": 2,
  "Rav 4": 3,
  "Hiace": 224,
  "Etios": 225,
  "SW4": 226,
  "Yaris": 227,
  "Corolla Cross": 245
};

// Buscar coincidencia de modelo en el string (case insensitive)
let modelo_code = null;
for (const [nombre, codigo] of Object.entries(modeloMap)) {
  const regex = new RegExp(nombre, "i");
  if (regex.test(modelo)) {
    modelo_code = codigo;
    break;
  }
}

// Retornar con los nuevos campos
return [
  {
    json: {
      ...item.json,
      tipoOrigen,
      formaDePago,
      usado,
      bocadeventa,
      modelo_code
    }
  }
];
